import { db } from "@/src/prisma/db";
import { getKitchenDeliveryDistances, isWithinDeliveryRadius, MAX_DELIVERY_DISTANCE_METERS } from "@/src/lib/location";
import { isDeliveryRadiusEnforced, isNationwideDevelopmentMode, isNationwideDevelopmentSeller, isKitchenLocationAllowed } from "@/src/lib/feature-flags";
import { normalizeCatalogSearchText } from "@/src/lib/catalog-filter";

export const runtime = "nodejs";

const average = (ratings: Array<{ rating: number }>) => ratings.length ? ratings.reduce((sum, row) => sum + row.rating, 0) / ratings.length : null;
const cuisineOf = (description: string | null, _city: string | null) => description?.match(/inspired by ([\w -]+?) home cooking/i)?.[1] ?? "Home cooking";
const dishTerms = (dish: { name: string; category: string; cuisine: string }) => `${dish.name} ${dish.category} ${dish.cuisine}`.toLowerCase();
const sweets = /dessert|sweet|cake|pie|tart|pudding|baklava|jamun|kunafa|mochi|churro|ice cream|halwa|cheesecake|tiramisu|mämmi|korvapuusti|pastry|brownie|cookie|donut/i;
const plantBased = /vegetarian|vegan|plant-based|salad|tofu|lentil|chickpea/i;

export async function GET(request: Request) {
  try {
    const url = new URL(request.url);
    const latParam = url.searchParams.get("lat");
    const lngParam = url.searchParams.get("lng");
    const hasLocation = latParam !== null && lngParam !== null && Number.isFinite(Number(latParam)) && Number.isFinite(Number(lngParam));
    const customerLocation = hasLocation ? { latitude: Number(latParam), longitude: Number(lngParam) } : null;
    const shopRows = await db.orm.public.Shop
      .where({ status: "ACTIVE", isOnline: true })
      .include("menuItems", (items) => items.where({ isAvailable: true }).include("category", (category) => category.select("name")).orderBy((item) => item.sortOrder.asc()))
      .include("reviews", (reviews) => reviews.select("rating"))
      .include("seller", (seller) => seller.select("name", "email"))
      .orderBy((shop) => shop.name.asc())
      .all();
    const allShops = shopRows.filter((shop) => isKitchenLocationAllowed(shop.address) && (!isNationwideDevelopmentMode() || isNationwideDevelopmentSeller(shop.seller)));
    const deliveryChecks = new Map<number, { eligible: boolean; distanceKm: number | null; unavailableReason?: string }>();
    let routeCheckFailed = false;
    if (customerLocation && isDeliveryRadiusEnforced()) {
      allShops.filter((shop) => shop.latitude == null || shop.longitude == null).forEach((shop) => deliveryChecks.set(shop.id, { eligible: false, distanceKm: null, unavailableReason: "Kitchen location missing" }));
      const locatedShops = allShops.filter((shop) => shop.latitude != null && shop.longitude != null);
      try {
        const distances = await getKitchenDeliveryDistances(customerLocation, locatedShops.map((shop) => ({ latitude: shop.latitude!, longitude: shop.longitude! })));
        locatedShops.forEach((shop, index) => {
          const meters = distances[index];
          deliveryChecks.set(shop.id, meters == null
            ? { eligible: false, distanceKm: null, unavailableReason: "Delivery distance could not be checked" }
            : { eligible: isWithinDeliveryRadius(meters), distanceKm: meters / 1000, unavailableReason: isWithinDeliveryRadius(meters) ? undefined : "Too far for delivery" });
        });
        routeCheckFailed = distances.some((distance) => distance === null) && locatedShops.length > 0;
      } catch { routeCheckFailed = true; locatedShops.forEach((shop) => deliveryChecks.set(shop.id, { eligible: false, distanceKm: null, unavailableReason: "Delivery distance could not be checked" })); }
    }
    const includeUnavailable = url.searchParams.get("includeUnavailable") === "1";
    if (customerLocation && isNationwideDevelopmentMode()) {
      allShops.forEach((shop) => deliveryChecks.set(shop.id, { eligible: true, distanceKm: null }));
    }
    const eligibleShops = customerLocation && isDeliveryRadiusEnforced() ? allShops.filter((shop) => deliveryChecks.get(shop.id)?.eligible) : allShops;
    const shops = customerLocation && includeUnavailable ? allShops : eligibleShops;
    const eligibleCount = [...deliveryChecks.values()].filter((check) => check.eligible).length;
    const locationStatus = customerLocation ? { checked: !routeCheckFailed, available: eligibleCount > 0, kitchenCount: eligibleCount, routeCheckFailed, maximumDeliveryDistanceKm: MAX_DELIVERY_DISTANCE_METERS / 1000, radiusEnforced: isDeliveryRadiusEnforced(), nationwideDevelopmentMode: isNationwideDevelopmentMode() } : null;

    const allDishes = eligibleShops.flatMap((shop) => {
      const rating = average(shop.reviews ?? []);
      const cuisine = cuisineOf(shop.description, shop.city);
      return (shop.menuItems ?? []).map((item) => ({
        id: item.id, shopId: shop.id, name: item.name, shop: shop.name, cuisine,
        category: item.category?.name ?? "Other", price: item.price, rating,
        time: shop.estimatedMinutes == null ? "Estimate unavailable" : `${shop.estimatedMinutes} min`, estimatedMinutes: shop.estimatedMinutes,
        deliveryDistanceKm: deliveryChecks.get(shop.id)?.distanceKm ?? null, image: item.imageUrl,
        description: item.description ?? "Made fresh by a local home cook.",
        deliveryFee: shop.deliveryFee ?? 2.5, isFeatured: item.isFeatured,
      }));
    });

    const query = normalizeCatalogSearchText(url.searchParams.get("q")?.trim() ?? "");
    if (query.length >= 2) {
      const results = allDishes.filter((dish) => normalizeCatalogSearchText(`${dish.name} ${dish.shop} ${dish.cuisine} ${dish.category} ${dish.description}`).includes(query)).slice(0, 40);
      const kitchens = shops
        .filter((shop) => normalizeCatalogSearchText(`${shop.name} ${shop.description ?? ""} ${shop.city ?? ""} ${cuisineOf(shop.description, shop.city)}`).includes(query))
        .slice(0, 12)
        .map((shop) => ({
          id: shop.id, name: shop.name, description: shop.description, logoUrl: shop.logoUrl,
          coverImageUrl: shop.coverImageUrl, city: shop.city, status: shop.status, isOnline: shop.isOnline,
          cuisine: cuisineOf(shop.description, shop.city), deliveryFee: shop.deliveryFee,
          estimatedMinutes: shop.estimatedMinutes, minimumOrder: shop.minimumOrder,
          distanceKm: deliveryChecks.get(shop.id)?.distanceKm ?? null,
          deliveryDistanceKm: deliveryChecks.get(shop.id)?.distanceKm ?? null,
          deliverable: customerLocation ? deliveryChecks.get(shop.id)?.eligible ?? false : null,
          deliveryStatus: customerLocation ? deliveryChecks.get(shop.id)?.unavailableReason ?? "Available for delivery" : null,
        }));
      return Response.json({ results, kitchens, locationStatus });
    }

    const [orderItems, favorites] = await Promise.all([
      db.orm.public.OrderItem.orderBy((item) => item.createdAt.desc()).limit(1000).include("order", (order) => order.select("status")).include("menuItem", (item) => item.select("id", "shopId")).all(),
      db.orm.public.Favorite.all(),
    ]);
    const orderCounts = new Map<number, number>();
    const kitchenOrders = new Map<number, number>();
    for (const row of orderItems) {
      if (["CANCELLED", "REFUNDED"].includes(row.order?.status ?? "")) continue;
      orderCounts.set(row.menuItemId, (orderCounts.get(row.menuItemId) ?? 0) + row.quantity);
      kitchenOrders.set(row.menuItem?.shopId ?? 0, (kitchenOrders.get(row.menuItem?.shopId ?? 0) ?? 0) + row.quantity);
    }
    const favoriteCounts = new Map<number, number>();
    const kitchenFavorites = new Map<number, number>();
    for (const favorite of favorites) {
      favoriteCounts.set(favorite.menuItemId, (favoriteCounts.get(favorite.menuItemId) ?? 0) + 1);
      kitchenFavorites.set(favorite.shopId, (kitchenFavorites.get(favorite.shopId) ?? 0) + 1);
    }
    const dishes = allDishes.map((dish) => ({ ...dish, orderCount: orderCounts.get(dish.id) ?? 0, favoriteCount: favoriteCounts.get(dish.id) ?? 0 }));
    const kitchens = shops.map((shop) => ({
      id: shop.id, name: shop.name, description: shop.description, logoUrl: shop.logoUrl,
      coverImageUrl: shop.coverImageUrl, city: shop.city, status: shop.status, isOnline: shop.isOnline,
      cuisine: cuisineOf(shop.description, shop.city), deliveryFee: shop.deliveryFee,
      estimatedMinutes: shop.estimatedMinutes, minimumOrder: shop.minimumOrder,
      createdAt: shop.createdAt, rating: average(shop.reviews ?? []),
      reviewCount: shop.reviews?.length ?? 0, orderCount: kitchenOrders.get(shop.id) ?? 0,
      favoriteCount: kitchenFavorites.get(shop.id) ?? 0,
      latitude: shop.latitude, longitude: shop.longitude,
      distanceKm: deliveryChecks.get(shop.id)?.distanceKm ?? null,
      deliverable: customerLocation ? deliveryChecks.get(shop.id)?.eligible ?? false : null,
      deliveryStatus: customerLocation ? deliveryChecks.get(shop.id)?.unavailableReason ?? "Available for delivery" : null,
      deliveryDistanceKm: deliveryChecks.get(shop.id)?.distanceKm ?? null,
      pickupAvailable: false,
    }));

    // One pass per seller keeps every food carousel varied. Once a dish is featured,
    // the next sections prioritize unseen items instead of repeating it.
    const used = new Set<number>();
    const curated = (source: typeof dishes, limit = 14, uniqueAcrossSections = true) => {
      const candidates = [...source].sort((a, b) => b.orderCount - a.orderCount || b.favoriteCount - a.favoriteCount || Number(b.isFeatured) - Number(a.isFeatured) || (b.rating ?? 0) - (a.rating ?? 0));
      const chosen: typeof dishes = [];
      const chosenShops = new Set<number>();
      for (const item of candidates) {
        if (chosen.length >= limit) break;
        if ((uniqueAcrossSections && used.has(item.id)) || chosenShops.has(item.shopId)) continue;
        chosen.push(item); chosenShops.add(item.shopId);
      }
      for (const item of candidates) {
        if (chosen.length >= limit) break;
        if ((uniqueAcrossSections && used.has(item.id)) || chosen.some((row) => row.id === item.id)) continue;
        chosen.push(item);
      }
      // Keep narrow collections useful after higher-priority shelves have claimed
      // the most popular dishes. Reuse a dish across shelves only as a last resort.
      for (const item of candidates) {
        if (chosen.length >= limit) break;
        if (!chosen.some((row) => row.id === item.id)) chosen.push(item);
      }
      if (uniqueAcrossSections) chosen.forEach((item) => used.add(item.id));
      return chosen;
    };
    const kitchenDiverse = (source: typeof kitchens, limit = 12) => {
      const chosen: typeof kitchens = [];
      const cuisines = new Set<string>();
      for (const kitchen of source) {
        if (chosen.length >= limit) break;
        if (!cuisines.has(kitchen.cuisine.toLowerCase())) { chosen.push(kitchen); cuisines.add(kitchen.cuisine.toLowerCase()); }
      }
      for (const kitchen of source) if (chosen.length < limit && !chosen.some((row) => row.id === kitchen.id)) chosen.push(kitchen);
      return chosen;
    };
    const popularity = [...dishes].sort((a, b) => b.orderCount - a.orderCount || (b.rating ?? 0) - (a.rating ?? 0));
    const topRated = [...dishes].filter((dish) => (dish.rating ?? 0) >= 4.5 || dish.isFeatured).sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0) || Number(b.isFeatured) - Number(a.isFeatured));
    const favourites = [...dishes].filter((dish) => dish.favoriteCount > 0).sort((a, b) => b.favoriteCount - a.favoriteCount);
    const quick = dishes.filter((dish) => Number.parseInt(dish.time, 10) <= 30);
    const international = dishes.filter((dish) => !/bangla|bengali|bangladeshi/i.test(dish.cuisine));
    const healthy = dishes.filter((dish) => plantBased.test(`${dish.category} ${dish.name}`));
    const desserts = dishes.filter((dish) => sweets.test(dishTerms(dish)));
    const avgRating = (kitchen: typeof kitchens[number]) => kitchen.rating ?? 0;
    const featuredKitchens = [...kitchens].sort((a, b) => avgRating(b) - avgRating(a) || b.favoriteCount - a.favoriteCount);
    const popularKitchens = [...kitchens].sort((a, b) => b.orderCount - a.orderCount || avgRating(b) - avgRating(a));
    const newKitchens = [...kitchens].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
    const internationalKitchens = [...kitchens].filter((kitchen) => !/bangla|bengali|bangladeshi/i.test(kitchen.cuisine));
    const sections = [
      { id: "top-picks", title: "Top Picks for You", kind: "food", href: "/collections/top-picks", description: "Featured dishes and highly rated favourites across local kitchens.", items: curated(topRated) },
      { id: "popular-right-now", title: "Popular Right Now", kind: "food", href: "/collections/popular-right-now", description: "Ranked by orders placed and favourites saved on HomeFoods.", items: curated(popularity) },
      { id: "homemade-favourites", title: "Homemade Favourites", kind: "food", href: "/collections/homemade-favourites", description: "Meals customers have added to their favourites.", items: curated(favourites.length ? favourites : dishes.filter((dish) => dish.isFeatured)) },
      { id: "delicious-deals", title: "Delicious Deals", kind: "food", href: "/collections/delicious-deals", description: "Verified discounts from participating kitchens.", items: [] as typeof dishes },
      { id: "quick-bites", title: "Quick Bites", kind: "food", href: "/collections/quick-bites", description: "Menus from kitchens with a 30-minute or quicker delivery estimate.", items: curated(quick) },
      { id: "international-flavours", title: "International Flavours", kind: "food", href: "/collections/international-flavours", description: "Explore a mix of cuisines made by cooks in your area.", items: curated(international) },
      { id: "healthy-choices", title: "Healthy Choices", kind: "food", href: "/collections/healthy-choices", description: "Vegetarian, plant-based, salad and lentil menu categories; nutrition data is not provided.", items: curated(healthy) },
      { id: "sweet-treats", title: "Sweet Treats & Desserts", kind: "food", href: "/collections/sweet-treats", description: "Desserts, bakes and sweet menu favourites.", items: curated(desserts) },
      { id: "featured-kitchens", title: "Featured Kitchens", kind: "kitchen", href: "/kitchens?collection=featured-kitchens", description: "Home kitchens with standout ratings and customer saves.", items: kitchenDiverse(featuredKitchens) },
      { id: "popular-restaurants", title: "Popular Restaurants", kind: "kitchen", href: "/kitchens?collection=popular-restaurants", description: "Sorted by the number of dishes ordered.", items: kitchenDiverse(popularKitchens) },
      { id: "new-on-homefoods", title: "New on HomeFoods", kind: "kitchen", href: "/kitchens?collection=new-on-homefoods", description: "Recently joined kitchens with active menus.", items: kitchenDiverse(newKitchens) },
      { id: "international-kitchens", title: "Explore International Kitchens", kind: "kitchen", href: "/kitchens?collection=international-kitchens", description: "Meet cooks sharing food from around the world.", items: kitchenDiverse(internationalKitchens) },
    ];
    const collectionId = new URL(request.url).searchParams.get("collection");
    if (collectionId) {
      const section = sections.find((row) => row.id === collectionId);
      if (!section) return Response.json({ error: "Collection not found." }, { status: 404 });
      const collectionItems: Record<string, typeof dishes | typeof kitchens> = {
        "top-picks": topRated, "popular-right-now": popularity,
        "homemade-favourites": favourites.length ? favourites : dishes.filter((dish) => dish.isFeatured),
        "delicious-deals": [], "quick-bites": quick, "international-flavours": international,
        "healthy-choices": healthy, "sweet-treats": desserts, "featured-kitchens": featuredKitchens,
        "popular-restaurants": popularKitchens, "new-on-homefoods": newKitchens,
        "international-kitchens": internationalKitchens,
      };
      const rows = (collectionItems[collectionId] ?? []) as Array<(typeof dishes)[number] | (typeof kitchens)[number]>;
      return Response.json({ collection: { id: section.id, title: section.title, kind: section.kind, description: section.description }, items: rows, locationStatus });
    }
    return Response.json({ sections, dishes, shops: kitchens, locationStatus });
  } catch (error) {
    console.error("Catalog request failed", error);
    return Response.json({ sections: [], dishes: [], shops: [], error: "The menu database is unavailable. Check the database connection." }, { status: 503 });
  }
}

"use client";

import { useEffect, useMemo, useState, type CSSProperties } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";

type Row = Record<string, unknown>;
const rows = (value: unknown): Row[] => Array.isArray(value) ? value as Row[] : [];
const readable = (value: unknown) => String(value ?? "Upcoming").replaceAll("_", " ").toLowerCase().replace(/\b\w/g, (letter) => letter.toUpperCase());
const HELSINKI = "Europe/Helsinki";
const dateText = (value: unknown, options: Intl.DateTimeFormatOptions = { weekday: "long", day: "numeric", month: "long" }) => new Intl.DateTimeFormat("en-GB", { ...options, timeZone: HELSINKI }).format(new Date(String(value)));

function actualMealStatus(meal: Row) {
  const order = (meal.order as Row | undefined) ?? {};
  const delivery = (order.delivery as Row | undefined) ?? {};
  if (delivery.status === "DELIVERED" || order.status === "DELIVERED") return "DELIVERED";
  if (delivery.status === "FAILED") return "FAILED";
  const latestDeliveryEvent = rows(order.statusEvents).filter((event) => String(event.domain) === "DELIVERY").sort((a, b) => new Date(String(b.createdAt ?? 0)).getTime() - new Date(String(a.createdAt ?? 0)).getTime())[0];
  if (latestDeliveryEvent?.status === "DELAYED") return "DELAYED";
  if (delivery.status === "IN_TRANSIT") return "ON_THE_WAY";
  if (delivery.status === "PICKED_UP") return "PICKED_UP";
  if (["ACCEPTED", "ASSIGNED"].includes(String(delivery.status))) return "RIDER_ASSIGNED";
  if (order.status === "READY_FOR_PICKUP") return "READY_FOR_DELIVERY";
  if (order.status === "PREPARING") return "PREPARING";
  if (order.status === "CONFIRMED") return "ORDER_ACCEPTED";
  if (order.status === "CANCELLED") return "CANCELLED";
  if (order.status === "PENDING") return "ORDER_RECEIVED";
  return String(meal.status ?? "UPCOMING");
}

export default function MealPlansPage() {
  const router = useRouter();
  const [subscriptions, setSubscriptions] = useState<Row[]>([]);
  const [selected, setSelected] = useState("");
  const [cursor, setCursor] = useState(() => new Date());
  const [view, setView] = useState<"week" | "month">("week");
  const [selectedMeal, setSelectedMeal] = useState<Row | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [connected, setConnected] = useState(true);

  useEffect(() => {
    let active = true;
    let authenticated = false;
    let hadSubscriptions = false;
    const refresh = async () => {
      try {
        if (!authenticated) {
          const auth = await fetch("/api/auth", { cache: "no-store" }).then((response) => response.json());
          if (!auth.user) { router.replace("/signin?returnTo=%2Fmeal-plans"); return; }
          if (auth.user.role !== "CUSTOMER") { router.replace("/workspace"); return; }
          authenticated = true;
        }
        const response = await fetch("/api/subscriptions", { cache: "no-store" });
        const payload = await response.json();
        if (!response.ok) throw new Error(payload.error ?? "Meal plans are unavailable.");
        if (!active) return;
        const next = rows(payload.subscriptions);
        setSubscriptions(next);
        hadSubscriptions = next.length > 0;
        setSelected((current) => current || String(next[0]?.id ?? ""));
        setConnected(true); setError("");
      } catch (cause) {
        if (active) { setConnected(false); if (!hadSubscriptions) setError(cause instanceof Error ? cause.message : "Meal plans are unavailable."); }
      } finally { if (active) setLoading(false); }
    };
    void refresh();
    const timer = window.setInterval(() => { if (document.visibilityState === "visible") void refresh(); }, 10_000);
    const onVisible = () => { if (document.visibilityState === "visible") void refresh(); };
    document.addEventListener("visibilitychange", onVisible);
    return () => { active = false; window.clearInterval(timer); document.removeEventListener("visibilitychange", onVisible); };
  }, [router]);

  const current = subscriptions.find((item) => String(item.id) === selected) ?? subscriptions[0];
  const plan = (current?.plan as Row | undefined) ?? {};
  const kitchen = (plan.shop as Row | undefined) ?? {};
  const meals = rows(current?.scheduledMeals).slice().sort((a, b) => new Date(String(a.scheduledAt)).getTime() - new Date(String(b.scheduledAt)).getTime());
  const delivered = meals.filter((meal) => actualMealStatus(meal) === "DELIVERED").length;
  const percent = meals.length ? Math.round(delivered / meals.length * 100) : 0;
  const nextMeal = meals.find((meal) => !["DELIVERED", "CANCELLED", "FAILED"].includes(actualMealStatus(meal)));
  const monthMeals = new Map(meals.map((meal) => [dateText(meal.scheduledAt, { year: "numeric", month: "2-digit", day: "2-digit" }), meal]));
  const weekDays = useMemo(() => {
    const weekday = Number(new Intl.DateTimeFormat("en-US", { timeZone: HELSINKI, weekday: "short" }).format(cursor) === "Sun" ? 0 : new Intl.DateTimeFormat("en-US", { timeZone: HELSINKI, weekday: "short" }).format(cursor) === "Mon" ? 1 : new Intl.DateTimeFormat("en-US", { timeZone: HELSINKI, weekday: "short" }).format(cursor) === "Tue" ? 2 : new Intl.DateTimeFormat("en-US", { timeZone: HELSINKI, weekday: "short" }).format(cursor) === "Wed" ? 3 : new Intl.DateTimeFormat("en-US", { timeZone: HELSINKI, weekday: "short" }).format(cursor) === "Thu" ? 4 : new Intl.DateTimeFormat("en-US", { timeZone: HELSINKI, weekday: "short" }).format(cursor) === "Fri" ? 5 : 6);
    const base = new Date(cursor); base.setDate(base.getDate() - weekday + 1);
    return Array.from({ length: 7 }, (_, index) => { const date = new Date(base); date.setDate(base.getDate() + index); return date; });
  }, [cursor]);
  const monthCells = useMemo(() => {
    const first = new Date(cursor.getFullYear(), cursor.getMonth(), 1);
    const start = new Date(first); start.setDate(first.getDate() - ((first.getDay() + 6) % 7));
    return Array.from({ length: 42 }, (_, index) => { const date = new Date(start); date.setDate(start.getDate() + index); return date; });
  }, [cursor]);
  const dayKey = (date: Date) => new Intl.DateTimeFormat("en-GB", { timeZone: HELSINKI, year: "numeric", month: "2-digit", day: "2-digit" }).format(date);
  const mealFor = (date: Date) => monthMeals.get(dayKey(date));
  const shiftCursor = (direction: number) => setCursor((old) => { const next = new Date(old); if (view === "month") next.setMonth(old.getMonth() + direction); else next.setDate(old.getDate() + direction * 7); return next; });


  return <main id="main-content" tabIndex={-1} className="orders-page meal-tracking-page">


    <section className="meal-tracking-content"><p className={connected ? "meal-connection" : "meal-connection offline"} role="status">{connected ? "Live updates" : "Reconnecting"}</p><span className="eyebrow"><span className="eyebrow-line"/> A LITTLE ROUTINE</span><h1>Your meal plans</h1><p className="orders-intro">Every delivery, kitchen update and completed meal in one place.</p>
      {loading ? <div className="orders-loading" role="status">Loading your meal schedule…</div> : error ? <div className="orders-error" role="alert">{error}<button onClick={() => window.location.reload()}>Try again</button></div> : subscriptions.length === 0 ? <div className="orders-empty"><span>✦</span><h2>No meal plans yet</h2><p>Your purchased meal plans and delivery schedule will appear here.</p><Link href="/workspace">Explore meal plans →</Link></div> : <>
        <label className="meal-plan-picker">Choose a plan<select value={String(current?.id ?? "")} onChange={(event) => { setSelected(event.target.value); setSelectedMeal(null); }} aria-label="Choose a meal plan">{subscriptions.map((subscription) => { const choice = (subscription.plan as Row | undefined) ?? {}; const choiceShop = (choice.shop as Row | undefined) ?? {}; return <option key={String(subscription.id)} value={String(subscription.id)}>{String(choice.name ?? "Meal plan")} · {String(choiceShop.name ?? "Home kitchen")}</option>; })}</select></label>
        <article className="meal-summary-card"><div className="meal-summary-copy"><span className="eyebrow">YOUR PURCHASED PLAN</span><h2>{String(plan.name ?? "Meal plan")}</h2><p>{String(kitchen.name ?? "Home kitchen")} · {readable(plan.type)} · {readable(current?.status)}</p><div className="meal-summary-dates"><span>Started <b>{dateText(current?.startDate)}</b></span>{Boolean(current?.endDate) && <span>Ends <b>{dateText(current?.endDate)}</b></span>}<span>{Number(plan.mealsPerPeriod ?? meals.length)} meals per billing period</span></div></div><div className="meal-progress-ring" style={{ "--meal-progress": `${percent}%` } as CSSProperties}><div><b>{delivered}</b><span>of {meals.length}</span></div></div><div className="meal-progress-text"><b>{meals.length ? `${delivered} of ${meals.length} deliveries completed` : "Schedule being confirmed"}</b><div className="meal-progress-bar"><i style={{ width: `${percent}%` }}/></div><small>{nextMeal ? `Next · ${dateText(nextMeal.scheduledAt)} at ${new Date(String(nextMeal.scheduledAt)).toLocaleTimeString("fi-FI", { timeZone: HELSINKI, hour: "2-digit", minute: "2-digit" })}` : meals.length ? "Every scheduled meal is complete" : "A schedule appears after payment confirmation."}</small></div></article>
        <div className="meal-calendar-toolbar"><div><span className="eyebrow">EUROPE / HELSINKI</span><h2>{view === "month" ? new Intl.DateTimeFormat("en-GB", { month: "long", year: "numeric", timeZone: HELSINKI }).format(cursor) : `${dateText(weekDays[0], { day: "numeric", month: "short" })} – ${dateText(weekDays[6], { day: "numeric", month: "short", year: "numeric" })}`}</h2></div><div className="meal-calendar-controls"><button onClick={() => shiftCursor(-1)} aria-label="Previous period">←</button><button onClick={() => setCursor(new Date())}>Today</button><button onClick={() => shiftCursor(1)} aria-label="Next period">→</button><div role="group" aria-label="Calendar view"><button aria-pressed={view === "week"} onClick={() => setView("week")}>Week</button><button aria-pressed={view === "month"} onClick={() => setView("month")}>Month</button></div></div></div>
        {view === "week" ? <div className="meal-week-grid">{weekDays.map((date) => { const meal = mealFor(date); const status = meal ? actualMealStatus(meal) : ""; return <button className={`meal-day-card ${meal ? `meal-${status.toLowerCase()}` : "meal-no-delivery"}`} key={date.toISOString()} onClick={() => meal && setSelectedMeal(meal)} disabled={!meal}><span>{date.toLocaleDateString("en-GB", { weekday: "short", timeZone: HELSINKI })}</span><b>{date.toLocaleDateString("en-GB", { day: "2-digit", timeZone: HELSINKI })}</b>{meal ? <><i aria-hidden="true">{status === "DELIVERED" ? "✓" : status === "UPCOMING" ? "◷" : "•"}</i><small>{readable(status)}</small></> : <small>No delivery</small>}</button>; })}</div> : <div className="meal-month-calendar"><div className="meal-weekday-labels">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((day) => <span key={day}>{day}</span>)}</div><div className="meal-month-grid">{monthCells.map((date) => { const meal = mealFor(date); const status = meal ? actualMealStatus(meal) : ""; return <button key={date.toISOString()} className={`${date.getMonth() === cursor.getMonth() ? "" : "outside-month"} ${meal ? `meal-${status.toLowerCase()}` : ""}`} onClick={() => meal && setSelectedMeal(meal)} disabled={!meal}><span>{date.toLocaleDateString("en-GB", { day: "numeric", timeZone: HELSINKI })}</span>{meal && <i aria-label={readable(status)}>{status === "DELIVERED" ? "✓" : "•"}</i>}</button>; })}</div></div>}
        {selectedMeal && <MealDetails meal={selectedMeal} kitchen={kitchen} plan={plan} onClose={() => setSelectedMeal(null)}/>}
        <section className="meal-deliveries-section"><div className="workspace-section-heading"><div><span className="eyebrow">REAL ORDERS · LIVE STATUS</span><h2>Scheduled deliveries</h2></div><span>{meals.length} in this billing period</span></div>{meals.length ? <div className="meal-delivery-list">{meals.map((meal, index) => { const status = actualMealStatus(meal); const order = (meal.order as Row | undefined) ?? {}; const delivery = (order.delivery as Row | undefined) ?? {}; const rider = ((delivery.rider as Row | undefined)?.user as Row | undefined) ?? {}; const lines = rows(order.items); return <button key={String(meal.id)} className={`meal-delivery-row meal-${status.toLowerCase()}`} onClick={() => setSelectedMeal(meal)}><span className="meal-row-date"><b>{dateText(meal.scheduledAt, { day: "2-digit" })}</b><small>{dateText(meal.scheduledAt, { month: "short" })}</small></span><span className="meal-row-main"><b>{lines.length ? lines.map((line) => `${String(line.quantity)} × ${String(line.name)}`).join(" · ") : `${readable(plan.name)} delivery ${index + 1}`}</b><small>{String(order.orderNumber ?? "Scheduled meal")} · {new Date(String(meal.scheduledAt)).toLocaleTimeString("fi-FI", { timeZone: HELSINKI, hour: "2-digit", minute: "2-digit" })}</small></span><span className="meal-row-status">{readable(status)}{status === "DELIVERED" && meal.deliveredAt ? <small>{dateText(meal.deliveredAt, { hour: "2-digit", minute: "2-digit" })}</small> : status === "RIDER_ASSIGNED" && rider.name ? <small>{String(rider.name)}</small> : null}</span></button>; })}</div> : <div className="meal-no-schedule"><span>◷</span><div><b>Schedule not available yet</b><p>We’ll show individual meal deliveries after the first subscription payment is confirmed. No future order is shown as in progress.</p></div></div>}</section>
        <div className="meal-plan-footer"><span>Menu and delivery updates come from your kitchen and rider’s order records.</span><Link href="/orders">View all orders →</Link></div>
      </>}
    </section>
  </main>;
}

function MealDetails({ meal, kitchen, plan, onClose }: { meal: Row; kitchen: Row; plan: Row; onClose: () => void }) {
  const order = (meal.order as Row | undefined) ?? {};
  const delivery = (order.delivery as Row | undefined) ?? {};
  const destination = (order.address as Row | undefined) ?? {};
  const lines = rows(order.items);
  return <div className="meal-detail-backdrop" role="presentation" onClick={onClose}><section className="meal-detail-panel" role="dialog" aria-modal="true" aria-labelledby="meal-detail-title" onClick={(event) => event.stopPropagation()}><button className="meal-detail-close" onClick={onClose} aria-label="Close meal details">×</button><span className="eyebrow">{dateText(meal.scheduledAt)}</span><h2 id="meal-detail-title">{lines.length ? lines.map((line) => String(line.name)).join(" · ") : String(plan.name ?? "Scheduled meal")}</h2><p>{String(kitchen.name ?? "Home kitchen")} · {readable(actualMealStatus(meal))}</p>{lines.map((line, index) => { const item = (line.menuItem as Row | undefined) ?? {}; return <div className="meal-detail-food" key={String(line.id ?? index)}>{typeof item.imageUrl === "string" && <img src={item.imageUrl} alt=""/>}<b>{String(line.quantity ?? 1)} × {String(line.name)}</b></div>; })}<dl><dt>Delivery window</dt><dd>{new Date(String(meal.scheduledAt)).toLocaleTimeString("fi-FI", { timeZone: HELSINKI, hour: "2-digit", minute: "2-digit" })} · Finland time</dd><dt>Delivery address</dt><dd>{String(destination.addressLine1 ?? "Saved delivery address")}, {String(destination.postalCode ?? "")} {String(destination.city ?? "")}</dd>{Boolean((delivery.rider as Row | undefined)?.user) && <><dt>Rider</dt><dd>{String(((delivery.rider as Row).user as Row).name ?? "Assigned rider")}</dd></>}{Boolean(order.notes) && <><dt>Notes</dt><dd>{String(order.notes)}</dd></>}</dl><p className="meal-detail-footnote">Meal status follows the kitchen order and delivery record. Tracking reflects confirmed updates only.</p></section></div>;
}

"use client";

import { useCallback, useEffect, useState, type FormEvent } from "react";
import AddressEditor from "./address-editor";
import SpotlightCard from "@/src/components/ui/spotlight-card";
import { OriginButton } from "@/src/components/ui/origin-button";

type Row = Record<string, unknown>;
const rows = (value: unknown) => Array.isArray(value) ? value as Row[] : [];
const money = (value: unknown) => new Intl.NumberFormat("fi-FI", { style: "currency", currency: "EUR" }).format(Number(value ?? 0));
const field = (data: FormData, key: string) => String(data.get(key) ?? "").trim();

export default function SellerKitchenEditor({ onSaved }: { onSaved: () => void }) {
  const [shop, setShop] = useState<Row>({});
  const [items, setItems] = useState<Row[]>([]);
  const [categories, setCategories] = useState<Row[]>([]);
  const [plans, setPlans] = useState<Row[]>([]);
  const [subscriptions, setSubscriptions] = useState<Row[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [confirm, setConfirm] = useState<{ title: string; action: () => Promise<void> } | null>(null);

  const load = useCallback(async () => {
    setLoading(true); setError("");
    try {
      const response = await fetch("/api/seller", { cache: "no-store" });
      const data = await response.json() as Row;
      if (!response.ok) throw new Error(String(data.error ?? "Seller kitchen could not be loaded."));
      setShop(data.shop && typeof data.shop === "object" ? data.shop as Row : {}); setItems(rows(data.items)); setCategories(rows(data.categories)); setPlans(rows(data.plans)); setSubscriptions(rows(data.subscriptions));
    } catch (issue) { setError(issue instanceof Error ? issue.message : "Seller kitchen could not be loaded."); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer); }, [load]);

  async function mutate(path: string, method: "POST" | "PATCH" | "DELETE", body: Row, message: string) {
    setBusy(true); setError(""); setNotice("");
    try {
      const response = await fetch(path, { method, headers: method === "DELETE" ? undefined : { "Content-Type": "application/json" }, body: method === "DELETE" ? undefined : JSON.stringify(body) });
      const data = await response.json() as Row;
      if (!response.ok) throw new Error(String(data.error ?? "Couldn't save that change."));
      setNotice(message); await load(); onSaved();
    } catch (issue) { setError(issue instanceof Error ? issue.message : "Couldn't save that change."); }
    finally { setBusy(false); }
  }

  function submit(event: FormEvent<HTMLFormElement>, action: (form: FormData) => Promise<void>) {
    event.preventDefault(); void action(new FormData(event.currentTarget));
  }

  if (loading) return <section className="workspace-section seller-editor" aria-busy="true"><div className="workspace-empty"><span className="loading-spinner"/><h2>Opening your kitchen…</h2><p>Loading your private kitchen, dishes and plans.</p></div></section>;
  if (!shop.id && !error) return <section id="kitchen-settings" className="workspace-section seller-editor initial-kitchen-setup"><div className="workspace-section-heading"><div><span className="eyebrow">YOUR KITCHEN</span><h2>Set up your kitchen</h2><p>Your seller account is ready. Add the basics now, then finish your Finnish delivery location and menu.</p></div></div>{notice && <p className="workspace-notice" role="status">{notice}</p>}<form className="workspace-form seller-editor-form" onSubmit={(event) => submit(event, (form) => mutate("/api/seller", "POST", { action: "create-kitchen", name: field(form, "name"), description: field(form, "description"), city: field(form, "city") }, "Kitchen created. Add your verified address and dishes to continue."))}><h3>Kitchen details</h3><label>Kitchen name<input name="name" required minLength={2} maxLength={100} placeholder="e.g. Tanvir’s home kitchen"/></label><label>City or town<input name="city" maxLength={80} required placeholder="Helsinki"/></label><label className="seller-kitchen-description">A little about your food<textarea name="description" rows={3} maxLength={1200} placeholder="Tell customers what you love to cook."/></label>{error && <p className="workspace-alert" role="alert">{error}</p>}<OriginButton type="submit" loading={busy} loadingText="Creating…">Create your kitchen <span>→</span></OriginButton><small>New kitchens start as pending review and stay private until approved.</small></form></section>;
  if (error && !shop.id) return <section className="workspace-section seller-editor"><div className="workspace-section-heading"><div><span className="eyebrow">YOUR KITCHEN</span><h2>We couldn’t open this kitchen</h2></div></div><p className="workspace-alert" role="alert">{error}</p><button type="button" onClick={() => void load()}>Try loading again</button></section>;

  return <section className="workspace-section seller-editor" id="seller-menu">
    <div className="workspace-section-heading"><div><span className="eyebrow">KITCHEN OPERATIONS</span><h2>{String(shop.name ?? "Your kitchen")}</h2><p>Changes here apply only to your kitchen.</p></div><span className="status-pill">{String(shop.status ?? "PENDING")}</span></div>
    {error && <p className="workspace-alert" role="alert">{error}</p>}{notice && <p className="workspace-notice" role="status">{notice}</p>}
    <div className="seller-editor-stats"><SpotlightCard className="spotlight-kpi" size="small" glowColor="green"><span>MENU DISHES</span><b>{items.length}</b></SpotlightCard><SpotlightCard className="spotlight-kpi" size="small" glowColor="orange"><span>AVAILABLE NOW</span><b>{items.filter((item) => Boolean(item.isAvailable)).length}</b></SpotlightCard><SpotlightCard className="spotlight-kpi" size="small" glowColor="purple"><span>MEAL PLANS</span><b>{plans.length}</b></SpotlightCard></div>

    <section className="seller-meal-schedule"><div className="workspace-section-heading"><div><span className="eyebrow">PLAN FULFILMENT</span><h3>Scheduled meal deliveries</h3><p>These are paid subscription orders, scheduled in Finland time.</p></div><span>{subscriptions.reduce((total, entry) => total + rows(entry.scheduledMeals).filter((meal) => !["DELIVERED", "CANCELLED", "FAILED"].includes(String(meal.status))).length, 0)} upcoming / active</span></div>{subscriptions.flatMap((subscription) => rows(subscription.scheduledMeals).map((meal) => ({ subscription, meal }))).filter(({ meal }) => !["DELIVERED", "CANCELLED", "FAILED"].includes(String(meal.status))).length ? <div className="workspace-list">{subscriptions.flatMap((subscription) => rows(subscription.scheduledMeals).map((meal) => ({ subscription, meal }))).filter(({ meal }) => !["DELIVERED", "CANCELLED", "FAILED"].includes(String(meal.status))).sort((a, b) => new Date(String(a.meal.scheduledAt)).getTime() - new Date(String(b.meal.scheduledAt)).getTime()).map(({ subscription, meal }) => { const order = (meal.order as Row | undefined) ?? {}; const customer = (subscription.customer as Row | undefined) ?? {}; const plan = (subscription.plan as Row | undefined) ?? {}; return <article className="workspace-card seller-meal-row" key={String(meal.id)}><div><b>{String(plan.name ?? "Meal plan")} · {new Date(String(meal.scheduledAt)).toLocaleString("fi-FI", { timeZone: "Europe/Helsinki", weekday: "short", day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" })}</b><span>{String(customer.name ?? customer.email ?? "Customer")} · Order {String(order.orderNumber ?? "pending")}</span><small>{rows(order.items).map((item) => `${String(item.quantity)} × ${String(item.name)}`).join(" · ") || "Menu is being confirmed"} · {String(meal.portions ?? 1)} portion(s)</small></div><span className="status-pill">{String(meal.status ?? order.status ?? "UPCOMING").replaceAll("_", " ")}</span><button type="button" onClick={() => { window.location.hash = "orders"; document.getElementById("orders")?.scrollIntoView({ behavior: "smooth" }); }}>Manage order</button></article>; })}</div> : <p className="workspace-muted">No paid meal-plan deliveries are scheduled. Future meals will appear here after successful subscription billing.</p>}</section>

    <form className="workspace-form seller-editor-form" onSubmit={(event) => submit(event, (form) => mutate("/api/seller", "POST", { name: field(form, "name"), description: field(form, "description"), imageUrl: field(form, "imageUrl"), price: Number(form.get("price")), categoryId: form.get("categoryId") ? Number(form.get("categoryId")) : null }, "Dish added to your menu."))}>
      <h3>Add a dish</h3><label>Dish name<input name="name" required minLength={2} placeholder="e.g. Sunday roast chicken"/></label><label>Description<input name="description" placeholder="What makes it lovely?"/></label><label>Price (€)<input name="price" type="number" step="0.01" min="0.5" max="500" required placeholder="12.50"/></label><label>Dish image URL<input name="imageUrl" type="url" placeholder="https://…"/></label><label>Category<select name="categoryId" defaultValue=""><option value="">No category</option>{categories.map((category) => <option key={String(category.id)} value={String(category.id)}>{String(category.name)}</option>)}</select></label><OriginButton type="submit" loading={busy} loadingText="Adding…">Add dish <span>+</span></OriginButton>
    </form>

    <form className="workspace-form seller-editor-form seller-category-form" onSubmit={(event) => submit(event, (form) => mutate("/api/seller", "POST", { action: "create-category", name: field(form, "name"), description: field(form, "description"), imageUrl: field(form, "imageUrl") }, "Menu category created."))}>
      <h3>Menu categories</h3><label>Category name<input name="name" required minLength={2} placeholder="Curries, breads…"/></label><label>Short description<input name="description" placeholder="Optional"/></label><label>Category image URL<input name="imageUrl" type="url" placeholder="https://…"/></label><OriginButton type="submit" variant="secondary" loading={busy}>Add category <span>+</span></OriginButton>
      {categories.length ? <div className="workspace-list">{categories.map((category) => <article className="workspace-card workspace-row" key={String(category.id)}><div><b>{String(category.name)}</b><span>{items.filter((item) => Number(item.categoryId) === Number(category.id)).length} dishes</span></div><button type="button" disabled={busy} onClick={() => { const name = window.prompt("Category name", String(category.name)); if (name === null) return; const imageUrl = window.prompt("Category image URL (leave blank to clear)", String(category.imageUrl ?? "")); if (imageUrl === null) return; void mutate("/api/seller", "PATCH", { action: "update-category", categoryId: category.id, name, imageUrl }, "Category updated."); }}>Edit</button><button type="button" className="confirm-danger" disabled={busy} onClick={() => setConfirm({ title: `Remove ${String(category.name)}?`, action: async () => { await mutate("/api/seller", "PATCH", { action: "delete-category", categoryId: category.id }, "Category removed."); } })}>Remove</button></article>)}</div> : <p className="workspace-muted">No categories yet. Add one to organize your menu.</p>}
    </form>

    <div className="workspace-list seller-menu-list"><h3>Your dishes</h3>{items.length ? items.map((item) => <form className="workspace-card seller-dish-editor" key={String(item.id)} onSubmit={(event) => submit(event, (form) => mutate("/api/seller", "PATCH", { itemId: item.id, name: field(form, "name"), description: field(form, "description"), price: Number(form.get("price")), imageUrl: field(form, "imageUrl"), categoryId: form.get("categoryId") ? Number(form.get("categoryId")) : null, isAvailable: form.get("isAvailable") === "on" }, "Dish changes saved."))}>
      <div className="workspace-card-top"><div><b>{String(item.name)}</b><span>{money(item.price)} · {item.isAvailable ? "Available" : "Paused"}</span></div></div><label>Dish name<input name="name" required defaultValue={String(item.name)}/></label><label>Description<input name="description" defaultValue={String(item.description ?? "")}/></label><div className="seller-dish-fields"><label>Price (€)<input name="price" type="number" step="0.01" min="0.5" max="500" defaultValue={String(item.price)}/></label><label>Category<select name="categoryId" defaultValue={String(item.categoryId ?? "")}><option value="">No category</option>{categories.map((category) => <option key={String(category.id)} value={String(category.id)}>{String(category.name)}</option>)}</select></label></div><label>Dish image URL<input name="imageUrl" type="url" placeholder="https://…" defaultValue={String(item.imageUrl ?? "")}/></label><label className="seller-availability"><input type="checkbox" name="isAvailable" defaultChecked={Boolean(item.isAvailable)}/> Available to order</label><div className="workspace-actions"><OriginButton type="submit" variant="secondary" loading={busy}>Save dish</OriginButton><button type="button" disabled={busy} className="confirm-danger" onClick={() => setConfirm({ title: `Remove ${String(item.name)} from your menu?`, action: async () => { await mutate(`/api/seller?itemId=${String(item.id)}`, "DELETE", {}, "Dish removed from the menu."); } })}>Remove dish</button></div>
    </form>) : <p className="workspace-muted">Your kitchen menu is empty. Add the first dish above.</p>}</div>

    <form className="workspace-form seller-editor-form" onSubmit={(event) => submit(event, (form) => mutate("/api/subscriptions", "POST", { action: "create-plan", name: field(form, "name"), description: field(form, "description"), type: field(form, "type"), price: Number(form.get("price")), mealsPerPeriod: Number(form.get("mealsPerPeriod")), menuItemIds: form.getAll("menuItemIds").map(Number) }, "Meal plan published."))}>
      <h3>Publish a meal plan</h3><label>Plan name<input name="name" required minLength={3}/></label><label>Description<input name="description"/></label><label>Billing period<select name="type"><option value="DAILY">Daily</option><option value="THREE_DAY">3 day</option><option value="WEEKLY">Weekly</option><option value="MONTHLY">Monthly</option></select></label><label>Price (€)<input name="price" type="number" step="0.01" min="1" max="2000" required/></label><label>Meals per billing period<input name="mealsPerPeriod" type="number" min="1" max="31" defaultValue="5"/></label><fieldset className="meal-plan-dish-options"><legend>Dishes included in every delivery</legend>{items.filter((item) => Boolean(item.isAvailable)).map((item) => <label key={String(item.id)}><input type="checkbox" name="menuItemIds" value={String(item.id)}/><span>{String(item.name)}</span></label>)}</fieldset><OriginButton type="submit" variant="promotional" loading={busy} loadingText="Publishing…">Publish plan <span>→</span></OriginButton>
      {plans.length ? <div className="workspace-list">{plans.map((plan) => <article className="workspace-card workspace-row" key={String(plan.id)}><div><b>{String(plan.name)}</b><span>{money(plan.price)} / {String(plan.type).toLowerCase()} · {plan.isActive ? "Published" : "Hidden"}</span><small>{rows(plan.items).length} included dishes</small></div><button type="button" disabled={busy} onClick={() => { const name = window.prompt("Plan name", String(plan.name)); if (name === null) return; const price = window.prompt("Price per period (€)", String(plan.price)); if (price === null) return; const description = window.prompt("Plan description", String(plan.description ?? "")); if (description === null) return; void mutate("/api/subscriptions", "PATCH", { planId: plan.id, name, price: Number(price), description }, "Meal plan updated."); }}>{plan.isActive ? "Edit plan" : "Edit hidden plan"}</button><button type="button" disabled={busy} onClick={() => void mutate("/api/subscriptions", "PATCH", { planId: plan.id, isActive: !plan.isActive }, plan.isActive ? "Meal plan hidden." : "Meal plan published.")}>{plan.isActive ? "Hide plan" : "Publish plan"}</button><details className="plan-dish-editor"><summary>Included dishes</summary><form className="workspace-form" onSubmit={(event) => submit(event, (form) => mutate("/api/subscriptions", "PATCH", { planId: plan.id, menuItemIds: form.getAll("menuItemIds").map(Number) }, "Meal plan dishes updated."))}>{items.filter((item) => Boolean(item.isAvailable)).map((item) => <label key={String(item.id)}><span><input type="checkbox" name="menuItemIds" value={String(item.id)} defaultChecked={rows(plan.items).some((entry) => Number(entry.menuItemId) === Number(item.id))}/> {String(item.name)}</span></label>)}<OriginButton type="submit" variant="secondary" loading={busy}>Save included dishes</OriginButton></form></details></article>)}</div> : <p className="workspace-muted">No meal plans yet.</p>}
    </form>
    {confirm && <div className="modal-backdrop" role="presentation" onClick={() => setConfirm(null)}><section className="confirm-modal" role="alertdialog" aria-modal="true"><span className="eyebrow">PLEASE CONFIRM</span><h2>{confirm.title}</h2><p>Dishes associated with order history are retained and hidden, so customer order records remain intact.</p><div className="confirm-actions"><button type="button" onClick={() => setConfirm(null)}>Keep it</button><button type="button" className="confirm-danger" onClick={() => { const action = confirm.action; setConfirm(null); void action(); }}>Confirm removal</button></div></section></div>}
  </section>;
}
